# ---------------------------------------------------------------- buffer
BUF = bytearray(W * H * 3)

NAVY_TOP = (16, 16, 50)
NAVY_BOT = (30, 30, 72)
SPOT = (74, 74, 138)
GLOW = (58, 58, 116)
GOLD = (212, 175, 55)
GOLD_LT = (233, 201, 96)
CREAM = (245, 240, 220)
WHITE = (255, 255, 255)
