PANTS = (42, 42, 62)


def _fill_gradient():
    for y in range(H):
        t = y / (H - 1)
        r = int(NAVY_TOP[0] + (NAVY_BOT[0] - NAVY_TOP[0]) * t)
        g = int(NAVY_TOP[1] + (NAVY_BOT[1] - NAVY_TOP[1]) * t)
        b = int(NAVY_TOP[2] + (NAVY_BOT[2] - NAVY_TOP[2]) * t)
        row = bytes((r, g, b)) * W
        BUF[y * W * 3:(y + 1) * W * 3] = row


def _blend(x, y, rgb, a):
    if a <= 0 or x < 0 or y < 0 or x >= W or y >= H:
        return
    i = (y * W + x) * 3
    if a >= 255:
        BUF[i] = rgb[0]
        BUF[i + 1] = rgb[1]
        BUF[i + 2] = rgb[2]
    else:
        BUF[i] = (rgb[0] * a + BUF[i] * (255 - a)) // 255
        BUF[i + 1] = (rgb[1] * a + BUF[i + 1] * (255 - a)) // 255
        BUF[i + 2] = (rgb[2] * a + BUF[i + 2] * (255 - a)) // 255


def _rect(x0, y0, x1, y1, rgb, a=255):
    x0 = max(0, x0)
    y0 = max(0, y0)
    x1 = min(W, x1)
    y1 = min(H, y1)
    if x1 <= x0 or y1 <= y0:
        return
    if a >= 255:
        row = bytes(rgb) * (x1 - x0)
        for y in range(y0, y1):
            BUF[y * W * 3 + x0 * 3:(y * W + x1) * 3] = row
    else:
        for y in range(y0, y1):
            for x in range(x0, x1):
                _blend(x, y, rgb, a)


def _disc(cx, cy, r, rgb, a=255):
    if r <= 0:
        return
    for y in range(max(0, cy - r), min(H, cy + r + 1)):
        dy = y - cy
        dx = int(math.sqrt(r * r - dy * dy))
        x0 = max(0, cx - dx)
        x1 = min(W, cx + dx + 1)
        if a >= 255:
            row = bytes(rgb) * (x1 - x0)
            BUF[y * W * 3 + x0 * 3:(y * W + x1) * 3] = row
        else:
            for x in range(x0, x1):
                _blend(x, y, rgb, a)


def _rounded_rect(x0, y0, x1, y1, rad, rgb):
    _rect(x0 + rad, y0, x1 - rad, y1, rgb)
    _rect(x0, y0 + rad, x1, y1 - rad, rgb)
    _disc(x0 + rad, y0 + rad, rad, rgb)
    _disc(x1 - rad, y0 + rad, rad, rgb)
    _disc(x0 + rad, y1 - rad, rad, rgb)
    _disc(x1 - rad, y1 - rad, rad, rgb)


def _poly(points, rgb, a=255):
    # Scanline fill for a simple polygon.
    ys = [p[1] for p in points]
    y0, y1 = max(0, min(ys)), min(H, max(ys))
    n = len(points)
    for y in range(y0, y1):
        xs = []
        for i in range(n):
            x0, yy0 = points[i]
            x1, yy1 = points[(i + 1) % n]
            if (yy0 <= y < yy1) or (yy1 <= y < yy0):
                t = (y - yy0) / (yy1 - yy0)
                xs.append(x0 + t * (x1 - x0))
        xs.sort()
        for j in range(0, len(xs) - 1, 2):
            xa, xb = int(math.ceil(xs[j])), int(math.floor(xs[j + 1]))
            if a >= 255:
                xa = max(0, xa)
                xb = min(W, xb)
                if xb > xa:
                    row = bytes(rgb) * (xb - xa)
                    BUF[y * W * 3 + xa * 3:(y * W + xb) * 3] = row
            else:
                for x in range(max(0, xa), min(W, xb)):
                    _blend(x, y, rgb, a)


def _arc(cx, cy, r, a0, a1, dot, rgb):
    # Stamp discs along an arc (angles in degrees, y grows downwards).
    for deg in range(a0, a1 + 1, 4):
        t = math.radians(deg)
        _disc(int(cx + r * math.cos(t)), int(cy + r * math.sin(t)),
              dot, rgb)


# ------------------------------------------------------------------- text
_ALPHA_CACHE = {}


def _glyph_alpha(ch, th):
    """Scale glyph ch to target height th; return (tw, alpha-bytes).

    Area-average downsampling of the embedded 1-bit bitmap via a summed
    area table, so text stays smooth at any size.
    """
    key = (ch, th)
    hit = _ALPHA_CACHE.get(key)
    if hit is not None:
        return hit
    _adv, w, h, _dy, hx = FONT[ch]
    if w == 0 or h == 0:
        res = (0, th, b"")
        _ALPHA_CACHE[key] = res
        return res
    raw = bytes.fromhex(hx)
    stride = (w + 7) // 8
    # Summed area table (h+1) x (w+1).
    ii = [0] * ((h + 1) * (w + 1))
    for yy in range(h):
        row_sum = 0
        base = yy * stride
        for xx in range(w):
            bit = (raw[base + (xx >> 3)] >> (7 - (xx & 7))) & 1
            row_sum += bit
            ii[(yy + 1) * (w + 1) + xx + 1] = (
                ii[yy * (w + 1) + xx + 1] + row_sum)

    def _I(fx, fy):
        ix = int(fx)
        iy = int(fy)
        if ix < 0:
            ix = 0
        if iy < 0:
            iy = 0
        if ix > w:
            ix = w
        if iy > h:
            iy = h
        ax = fx - ix
        ay = fy - iy
        if ix >= w:
            ax = 0.0
        if iy >= h:
            ay = 0.0
        s = w + 1
        a = ii[iy * s + ix]
        b = ii[iy * s + ix + 1] if ix < w else a
        c = ii[(iy + 1) * s + ix] if iy < h else a
        d = ii[(iy + 1) * s + ix + 1] if (ix < w and iy < h) else a
        return (a + ax * (b - a) + ay * (c - a)
                + ax * ay * (d - b - c + a))

    tw = max(1, int(round(w * th / h)))
    out = bytearray(tw * th)
    for oy in range(th):
        y0 = oy * h / th
        y1 = (oy + 1) * h / th
        for ox in range(tw):
            x0 = ox * w / tw
            x1 = (ox + 1) * w / tw
            area = (_I(x1, y1) - _I(x0, y1) - _I(x1, y0) + _I(x0, y0))
            cell = (x1 - x0) * (y1 - y0)
            v = int(255 * area / cell + 0.5) if cell > 0 else 0
            out[oy * tw + ox] = 255 if v > 255 else v
    res = (tw, bytes(out))
    _ALPHA_CACHE[key] = res
    return res


def _text_width(text, cap, tracking=0):
    scale = cap / CAP_H
    return sum(FONT[c][0] for c in text) * scale + tracking * max(0, len(text) - 1)


def _draw_text(text, cx, baseline, cap, rgb, tracking=0, max_w=None):
    """Draw text centered on cx; returns the width actually drawn."""
    width = _text_width(text, cap, tracking)
    scale = cap / CAP_H
    if max_w is not None and width > max_w:
        scale *= max_w / width
        width = max_w
    x = cx - width / 2.0
    for ch in text:
        adv, w, h, dy, _hx = FONT[ch]
        if w and h:
            th = max(1, int(round(h * scale)))
            tw, alpha = _glyph_alpha(ch, th)
            gx = int(round(x))
            gy = int(round(baseline + dy * scale))
            for oy in range(th):
                row = oy * tw
                for ox in range(tw):
                    a = alpha[row + ox]
                    if a:
                        _blend(gx + ox, gy + oy, rgb, a)
        x += adv * scale + tracking * scale
    return width


